CREATE TABLE email_verification_tokens(id BIGINT UNSIGNED AUTO_INCREMENT PRIMARY KEY,user_id BIGINT UNSIGNED NOT NULL,token_hash CHAR(64) NOT NULL,expires_at DATETIME NOT NULL,used_at DATETIME NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,UNIQUE KEY verification_token_unique(token_hash),KEY verification_user_created_idx(user_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
